function syncContactSettings(config) {
  const { spreadsheetId, tab, schema, table } = config;
  if (
    typeof spreadsheetId !== "string" ||
    !/^[A-Za-z0-9_-]{10,150}$/.test(spreadsheetId) ||
    spreadsheetId.startsWith("YOUR_") ||
    typeof tab !== "string" ||
    !tab.trim() ||
    tab.length > 100 ||
    /[\x00-\x1f]/.test(tab)
  )
    throw Error("Set the Google spreadsheet ID and tab name.");
  for (const identifier of [schema, table]) {
    if (
      typeof identifier !== "string" ||
      !/^[A-Za-z_][A-Za-z0-9_]{0,62}$/.test(identifier) ||
      identifier.startsWith("YOUR_")
    ) {
      throw Error(
        "Set the PostgreSQL schema and table using SQL identifier letters, numbers and underscores.",
      );
    }
  }
  const range = "'" + tab.replaceAll("'", "''") + "'!A:AZ";
  const url =
    "https://sheets.googleapis.com/v4/spreadsheets/" +
    spreadsheetId +
    "/values/" +
    encodeURIComponent(range) +
    "?majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE";
  return { ...config, url, relation: '"' + schema + '"."' + table + '"' };
}

const settings = {
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  tab: "Contacts",
  schema: "public",
  table: "YOUR_TABLE_NAME",
};
return [{ json: syncContactSettings(settings) }];

function readContactRows(reply, config) {
  const range = typeof reply?.range === "string" ? reply.range : "";
  const boundary = range.lastIndexOf("!");
  const tab = range.slice(0, boundary);
  const sheetName =
    tab.startsWith("'") && tab.endsWith("'") ? tab.slice(1, -1).replaceAll("''", "'") : tab;
  if (
    boundary < 1 ||
    sheetName !== config.tab ||
    reply.majorDimension !== "ROWS" ||
    !Array.isArray(reply.values) ||
    !Array.isArray(reply.values[0]) ||
    reply.values.length > 10001
  )
    throw Error("Expected the configured Sheets tab with a header and at most 10,000 rows.");
  const allowed = ["first_name", "last_name", "town", "age"];
  const header = reply.values[0];
  const indexes = allowed.map((label) => {
    const index = header.indexOf(label);
    if (index < 0 || header.lastIndexOf(label) !== index)
      throw Error("The sheet needs one header for each contact field.");
    return index;
  });
  const result = [],
    seen = new Set();
  function text(value, required, row) {
    if ((value == null || value === "") && !required) return null;
    if (
      typeof value !== "string" ||
      (required && !value.trim()) ||
      value.includes("\u0000") ||
      value.length > 2000
    ) {
      throw Error("Invalid text field at sheet row " + row + ".");
    }
    return value;
  }
  for (let i = 1; i < reply.values.length; i++) {
    const row = reply.values[i];
    if (!Array.isArray(row)) throw Error("Invalid sheet row " + (i + 1) + ".");
    const [first, last, town, age] = indexes.map((index) => row[index]);
    if ([first, last, town, age].every((value) => value == null || value === "")) continue;
    const rowNumber = i + 1;
    const first_name = text(first, true, rowNumber),
      last_name = text(last, true, rowNumber);
    const key = JSON.stringify([first_name, last_name]);
    if (seen.has(key)) throw Error("Duplicate full name at sheet row " + rowNumber + ".");
    seen.add(key);
    let years = null;
    if (age != null && age !== "") {
      years =
        typeof age === "number"
          ? age
          : typeof age === "string" && /^\d+$/.test(age)
            ? Number(age)
            : NaN;
      if (!Number.isInteger(years) || years < 0 || years > 2147483647)
        throw Error("Invalid integer age at sheet row " + rowNumber + ".");
    }
    result.push({ first_name, last_name, town: text(town, false, rowNumber), age: years });
  }
  return result;
}

function contactUpsert(relation) {
  return `WITH source_rows AS (
  SELECT first_name, last_name, town, age
  FROM jsonb_to_recordset($1::jsonb)
    AS uploaded(first_name text, last_name text, town text, age integer)
), changed AS (
  INSERT INTO ${relation} AS existing (first_name, last_name, town, age)
  SELECT first_name, last_name, town, age
  FROM source_rows
  ORDER BY first_name, last_name
  ON CONFLICT (first_name, last_name) DO UPDATE
  SET town = EXCLUDED.town, age = EXCLUDED.age
  WHERE (existing.town, existing.age) IS DISTINCT FROM (EXCLUDED.town, EXCLUDED.age)
  RETURNING 1
)
SELECT (SELECT count(*)::int FROM source_rows) AS source_rows,
       count(*)::int AS changed_rows
FROM changed;`;
}

const config = $("Set the source sheet and target table").first().json;
const rows = readContactRows($input.first().json.body, config);
const payload = JSON.stringify(rows);
if (Buffer.byteLength(payload, "utf8") > 1024 * 1024)
  throw Error("Keep the validated batch within 1 MiB.");
return [{ json: { query: contactUpsert(config.relation), payload, sourceRows: rows.length } }];

function checkContactReceipt(receipt, expected) {
  if (
    receipt?.source_rows !== expected ||
    !Number.isInteger(receipt?.changed_rows) ||
    receipt.changed_rows < 0 ||
    receipt.changed_rows > expected
  )
    throw Error("PostgreSQL did not confirm the synchronization counts.");
  return { sourceRows: expected, changedRows: receipt.changed_rows };
}

const expected = $("Validate and match the full contact names").first().json.sourceRows;
return [{ json: checkContactReceipt($input.first().json, expected) }];
